from pathlib import Path
P=Path(r'E:\CodexOutputs\ChemFlowAI\frontend\src')
(P/'pages/Steps.tsx').write_text(r'''import {useEffect,useState} from 'react';import {Play,Upload,FileJson,Check,SlidersHorizontal,Download,ExternalLink} from 'lucide-react';import {api,fmt} from '../api';import {Badge,Panel,Q,Notice,Metric,Empty} from '../components/ui';import {ProcessCanvas} from '../components/ProcessCanvas';import {EnergyChart,ParetoChart} from '../components/Charts';import type {Project,ProjectSpec} from '../types';
export type StepProps={p:Project;step:number;draft:ProjectSpec;setDraft:(s:ProjectSpec)=>void;model:string;setModel:(s:string)=>void;route:string;setRoute:(s:string)=>void;onSource:(q:any)=>void;onSelect:(q:any)=>void;run:(fn:()=>Promise<any>)=>Promise<any>;reload:()=>Promise<any>;busy:boolean;canEdit:boolean};
const routeText:Record<string,{title:string;desc:string;risks:string[]}>={route_a:{title:'普通精馏',desc:'反应、冷却、闪蒸、加热与单塔分离。',risks:['结构相对简单','需外部供热与冷却','近沸点体系需确认回流及塔板设计']},route_b:{title:'热泵精馏',desc:'压缩塔顶蒸气驱动再沸换热，包含闪蒸和循环。',risks:['引入压缩机和电力需求','依赖温差及压比可行性','两侧换热与循环收敛需要验证']},route_c:{title:'内部热耦合精馏',desc:'精馏段与提馏段分开，通过压缩和减压实现耦合。',risks:['需要温度匹配与热耦合模型','双塔压力与控制相互作用','最终比较需统一能量边界']},pyridine:{title:'多级分离与产品回收',desc:'采用实际结果表对应的开循环拓扑，包含正己烷进料和多级分离。',risks:['原始存档存在低温异常','当前版本无 DECanter / RE 回路','回流版本需另行提供完整数据']}};
export function Steps(props:StepProps){const {p,step,draft,setDraft,model,setModel,route,setRoute,onSource,onSelect,run,reload,busy,canEdit}=props;const [text,setText]=useState('');const [parseResult,setParseResult]=useState<any>(null);const [topology,setTopology]=useState<any>(null);const [comparison,setComparison]=useState<any[]>([]);const [vars,setVars]=useState<Record<string,number>>({column_pressure:12,reflux_ratio:10,feed_stage:20,compressor_ratio:1.5,split_fraction:.5});const [teaInputs,setTeaInputs]=useState<Record<string,any>>({basis_year:'',currency:'',hours:'',feed_price:'',product_price:'',utility_price:'',carbon_factor:'',method:'UTILITY_ONLY'});
 useEffect(()=>{if(step===7){api('/projects/'+p.id+'/comparison').then(setComparison).catch(()=>setComparison([]));if(p.optimization)setVars(Object.fromEntries(Object.entries(p.optimization.variables).map(([k,v]:any)=>[k,v.value])))}if(step===8&&p.tea)setTeaInputs(p.tea.inputs)},[step,p.id]);
 const updateFeed=(i:number,key:string,val:string)=>{const s=structuredClone(draft);const field=(s.feeds[i] as any)[key];field.value=val===''?null:Number(val);field.source_type='USER_INPUT';field.source_name='设计基准表单';field.status='UNVERIFIED';field.locator='';setDraft(s)};
 const parse=()=>run(async()=>{const res=await api('/projects/'+p.id+'/intake','POST',{text});setDraft(res.spec);setParseResult(res)});
 if(step===1)return <>
 <Panel title="原料与进料" kicker="01 / FEEDSTOCK SPECIFICATIONS" action={<Badge tone="cyan">INPUT ONLY</Badge>}>{draft.feeds.map((f,i)=><div className="feed-block" key={f.stream_id}><div className="feed-title"><h3>{f.stream_id}</h3><Q q={f.mass_flow} onSource={onSource}/></div><div className="form-grid">{[['temperature','温度 / °C'],['pressure','绝对压力 / bar'],['mass_flow','质量流量 / kg/h']].map(([key,label])=><label key={key}>{label}<input aria-label={f.stream_id+' '+label} type="number" step="any" value={(f as any)[key].value??''} onChange={e=>updateFeed(i,key,e.target.value)}/></label>)}</div></div>)}<p style={{marginTop:14}}>这里只显示已知进料。未来产品流股及 Aspen 下游结果不会传入本阶段。</p></Panel>
 <Panel title="产品目标与反应" kicker="02 / PRODUCT TARGETS"><div className="field-block"><small className="eyebrow">REACTION · USER INPUT</small><h3>{draft.reaction.equation}</h3></div><div className="form-grid two" style={{marginTop:14}}><label>目标产品<input value={draft.target_products[0].name} onChange={e=>{const s=structuredClone(draft);s.target_products[0].name=e.target.value;setDraft(s)}}/></label><label>目标纯度 / 质量分率（未知时留空）<input type="number" min="0" max="1" step=".001" value={draft.target_products[0].purity?.value??''} onChange={e=>{const s=structuredClone(draft);s.target_products[0].purity=e.target.value===''?null:{value:Number(e.target.value),unit:'fraction',source_type:'USER_INPUT',source_name:'设计基准表单',version:'1',status:'UNVERIFIED'};setDraft(s)}}/></label></div></Panel>
 <Panel title="公用工程与边界条件" kicker="03 / UTILITIES & CONSTRAINTS"><Notice>源数据未提供完整公用工程和产品规格。Demo 可在人工接受缺失后继续；真实设计需要补齐。</Notice><div className="form-grid two" style={{marginTop:14}}><label>公用工程说明<input placeholder="未提供；不自动填值" value={String(draft.utilities.description||'')} onChange={e=>{const s=structuredClone(draft);s.utilities=e.target.value?{description:e.target.value}:{};setDraft(s)}}/></label><label>工程约束<input placeholder="例如操作边界，需工程确认" value={String(draft.constraints.description||'')} onChange={e=>{const s=structuredClone(draft);s.constraints=e.target.value?{description:e.target.value}:{};setDraft(s)}}/></label></div></Panel>
 <Panel title="自然语言 / 文件输入" kicker="STRUCTURED INTAKE · RULE ENGINE"><textarea aria-label="自然语言输入" placeholder="例：温度 57 °C，压力 20 bar，流量 4409.652 kg/h。或粘贴完整 ProjectSpec JSON。" value={text} onChange={e=>setText(e.target.value)}/><div className="button-row"><button onClick={parse} disabled={!text||busy}><FileJson size={15}/>解析为设计基准</button><label className="upload-label"><Upload size={14}/> 导入 ProjectSpec JSON<input type="file" accept=".json" onChange={async e=>{const f=e.target.files?.[0];if(f)setText(await f.text())}}/></label></div>{parseResult&&<Notice tone="cyan">识别字段：{parseResult.recognized.join('、')||'无'}。{parseResult.unparsed.join(' ')}</Notice>}</Panel></>;
 if(step===2)return <><div className="metrics"><Metric label="输入组分" value={p.spec.components.length} sub="来自任务定义"/><Metric label="进料来源" value="ASPEN INPUT" sub="仅校核已知输入"/><Metric label="实验物性 / BIP" value="MISSING" sub="不能声称物性已验证" tone="amber"/></div><Panel title="组分主数据与二元参数" kicker="COMPONENT MASTER GRID"><div className="table-scroll"><table><thead><tr><th>组分</th><th>定义来源</th><th>Tc / Pc</th><th>二元参数</th><th>状态</th></tr></thead><tbody>{p.spec.components.map(c=><tr key={c.id}><td><b>{c.name}</b></td><td><button className="source-button" onClick={()=>onSource(c)}>{c.source_type} ⓘ</button></td><td>未提供</td><td>未提供</td><td><Badge tone="amber">MISSING</Badge></td></tr>)}</tbody></table></div></Panel><Panel title="输入温度 / 压力范围" kicker="PROPERTY VISUALIZATION"><div className="form-grid">{p.spec.feeds.map(f=><div className="field-block" key={f.stream_id}><h3>{f.stream_id}</h3><div className="keyvalue"><span>T</span><Q q={f.temperature} onSource={onSource}/></div><div className="keyvalue"><span>P</span><Q q={f.pressure} onSource={onSource}/></div></div>)}</div><Notice>没有实验 VLE 数据，因此不绘制拟合曲线、不计算拟合精度。{p.dataset==='pyridine'?'历史存档有异常标记，结果将在 Step 05 保留展示。':''}</Notice></Panel></>;
 if(step===3)return <><Panel title="候选热力学模型" kicker="PROPERTY METHOD SELECTION" action={<Badge tone="amber">HUMAN APPROVAL</Badge>}><div className="form-grid">{p.models.map((m:any)=><button className={'model-card '+(model===m.id?'active':'')} key={m.id} onClick={()=>setModel(m.id)} disabled={!canEdit}><h3>{m.id}</h3><Badge tone="amber">待验证</Badge><p>{m.reason}</p><p>{m.risk}</p><small>RULE · 工程候选规则</small></button>)}</div></Panel><Panel title="适用范围与验证条件" kicker="ENGINEERING REVIEW"><table><tbody><tr><td>混合物性质</td><td>{p.dataset==='pdh'?'烃类 / 氢气':'极性、强非理想多组分'}</td></tr><tr><td>实验 VLE 对照</td><td>NOT ASSESSED</td></tr><tr><td>所需参数</td><td>纯组分数据库、混合规则、BIP、有效温压范围</td></tr><tr><td>本轮确认含义</td><td>接受用于工作流演示的候选，不代表已通过独立物性验证</td></tr></tbody></table><Notice>Reference Replay 不会按所选模型重新求解，候选模型选择不改变存档数值。</Notice></Panel></>;
 if(step===4){const ids=p.dataset==='pdh'?['route_a','route_b','route_c']:['pyridine'];return <><Panel title="路线决策工作区" kicker="PROCESS ROUTE SCREENING"><div className="route-grid">{ids.map(id=><article className={'route-card '+(route===id?'selected':'')} key={id}><small className="eyebrow">{id.toUpperCase()}</small><h3>{routeText[id].title}</h3><p>{routeText[id].desc}</p><ul>{routeText[id].risks.map(x=><li key={x}>{x}</li>)}</ul><button onClick={()=>run(async()=>{setRoute(id);setTopology(await api('/projects/'+p.id+'/routes/'+id))})} disabled={!canEdit}>{route===id?<Check size={15}/>:null}{route===id?'已选择路线':'SELECT ROUTE'}</button></article>)}</div></Panel>{topology&&<Panel title="所选路线结构" kicker="SIMULATION IR · NO RESULTS"><div className="flex-row">{topology.units.map((u:any)=><Badge key={u.id} tone="cyan">{u.id} · {u.type}</Badge>)}</div><div className="table-scroll" style={{marginTop:16}}><table><thead><tr><th>流股</th><th>来源</th><th>去向</th></tr></thead><tbody>{topology.connections.map((c:any)=><tr key={c.stream_id}><td>{c.stream_id}</td><td>{c.from_unit||'进料边界'}</td><td>{c.to_unit||'产品边界'}</td></tr>)}</tbody></table></div></Panel>}<Notice tone="cyan">路线筛选使用输入与已有工程拓扑。此阶段不读取流股标准答案。</Notice></>}
 if(step===5)return <><Notice tone="amber">{p.mode==='demo'?'REFERENCE REPLAY：读取已有 Aspen 存档，验证工作流和数据映射；不是新一轮独立模拟。':'BLIND VALIDATION：专业模拟器尚未连接。禁止使用回放替代独立求解。'}</Notice><div className="flex-row"><button className="primary" disabled={busy||!canEdit} onClick={()=>run(async()=>{await api('/projects/'+p.id+'/simulate','POST');await reload()})}><Play size={15}/>{p.mode==='demo'?'加载参考回放':'运行专业模拟器'}</button><Badge tone={p.result?'cyan':'amber'}>{p.result?'REPLAY LOADED · NOT SOLVED':'SIMULATOR RESULT PENDING'}</Badge><span className="muted">{p.ir?.units.length} 设备 / {p.ir?.streams.length} 流股</span></div><ProcessCanvas id={p.id} revision={p.revision} onSelect={onSelect}/>{p.result&&<Panel title="流股结果表" kicker="SOURCE · ASPEN REFERENCE"><div className="table-scroll"><table><thead><tr><th>流股</th><th>T / °C</th><th>P / bar</th><th>质量流量 / kg/h</th><th>状态</th></tr></thead><tbody>{Object.values(p.result.streams).map((s:any)=><tr key={s.stream_id} onClick={()=>onSelect({kind:'stream',id:s.stream_id})} style={{cursor:'pointer'}}><td><b>{s.stream_id}</b></td><td><Q q={s.temperature} onSource={onSource}/></td><td><Q q={s.pressure} onSource={onSource}/></td><td><Q q={s.mass_flow} onSource={onSource}/></td><td><Badge tone={s.temperature.status==='ANOMALY'?'amber':'cyan'}>{s.temperature.status==='ANOMALY'?'SOURCE ANOMALY':'REFERENCE'}</Badge></td></tr>)}</tbody></table></div></Panel>}{p.review?.issues.map((x:string)=><Notice key={x}>{x}</Notice>)}</>;
 if(step===6)return <><div className="metrics"><Metric label="设备记录" value={p.ir.units.length} sub="源：SimulationIR"/><Metric label="报告的负荷项" value={p.result.energy.length} sub="源：Aspen Reference"/><Metric label="能量衡算" value="NOT ASSESSED" tone="amber" sub="缺少完整边界，不声明闭合"/></div><Panel title="设备热负荷与功率" kicker="ENERGY & EQUIPMENT" action={<Badge tone="cyan">ASPEN REFERENCE</Badge>}>{p.result.energy.length?<EnergyChart rows={p.result.energy} onSource={onSource}/>:<Empty title="设备负荷未提供" text="该存档未提供可对应的设备 duty，不计算热回收收益。"/>}</Panel><Panel title="物料衡算与设备状态" kicker="DETERMINISTIC REVIEW"><div className="form-grid"><Metric label="边界进料" value={fmt(p.review.balance.input_kg_h)+' kg/h'}/><Metric label="边界出料" value={fmt(p.review.balance.output_kg_h)+' kg/h'}/><Metric label="边界质量差" value={fmt(p.review.balance.residual_kg_h)+' kg/h'} tone="amber"/></div><button className="source-button" onClick={()=>onSource(p.review.balance)}>查看衡算公式与源流股 ⓘ</button><table style={{marginTop:16}}><thead><tr><th>设备</th><th>类型</th><th>求解状态</th></tr></thead><tbody>{p.ir.units.map((u:any)=><tr key={u.id}><td>{u.id}</td><td>{u.type}</td><td>REPLAY_NOT_SOLVED</td></tr>)}</tbody></table></Panel></>;
 if(step===7)return <><Notice tone="cyan">OPTIMIZATION PREVIEW / REFERENCE COMPARISON：滑块保存设计变量，不生成新的数值结果。参考点来自独立的历史工况，不代表最优解。</Notice><div className="optimization-grid"><Panel title="优化问题设置" kicker="DECISION VARIABLES"><p style={{marginBottom:18}}>初值与边界为可编辑演示设置（USER INPUT），不是模拟器推荐最优值。</p>{Object.entries(vars).filter(([k])=>p.route==='route_b'||!['compressor_ratio','split_fraction'].includes(k)).map(([k,v])=>{const defs:Record<string,[string,number,number,number]>={column_pressure:['塔压 / bar',.1,30,.1],reflux_ratio:['回流比',.1,30,.1],feed_stage:['进料级',1,100,1],compressor_ratio:['压缩比',1,4,.05],split_fraction:['分流比',0,1,.01]};const [label,min,max,inc]=defs[k];return <div className="range-row" key={k}><label htmlFor={k}>{label}<output>{v}</output></label><input id={k} type="range" min={min} max={max} step={inc} value={v} disabled={!canEdit} onChange={e=>setVars({...vars,[k]:Number(e.target.value)})}/><small className="muted">{min} — {max}</small></div>})}<button className="full-width" disabled={!canEdit||busy} onClick={()=>run(async()=>{await api('/projects/'+p.id+'/optimization','POST',{variables:vars,bounds:{source_type:'USER_INPUT',definition:'UI demonstration bounds; engineer review required'},select_baseline:true});await reload()})}><SlidersHorizontal size={15}/>保存问题并选用参考基线</button>{p.optimization&&<Badge tone="purple">REFERENCE BASELINE SELECTED</Badge>}</Panel><Panel title="多目标比较空间" kicker="NO OPTIMIZER CONNECTED"><ParetoChart rows={comparison}/><div className="main-stack" style={{marginTop:15}}>{comparison.map(r=><div className="field-block" key={r.id}><div className="feed-title"><h3>{r.title}</h3><Badge tone="purple">REFERENCE</Badge></div><div className="keyvalue"><span>正热负荷合计</span><Q q={r.thermal} onSource={onSource}/></div><div className="keyvalue"><span>报告的电功率</span><Q q={r.power} onSource={onSource}/></div></div>)}</div><Notice>目标：热负荷与电功率之间的权衡。没有统一价格及成本模型，不给综合优胜结论。</Notice></Panel></div></>;
 if(step===8)return <><Panel title="评价边界与假设" kicker="TECHNO-ECONOMIC / ENVIRONMENTAL INPUTS"><div className="form-grid">{[['basis_year','基准年','number'],['currency','币种','text'],['hours','年运行小时 / h','number'],['feed_price','统一原料单价 / 币种/kg','number'],['product_price','产品物流单价 / 币种/kg','number'],['utility_price','统一公用工程单价 / 币种/kWh','number'],['carbon_factor','统一排放因子 / kgCO₂e/kWh（可选）','number']].map(([k,l,t])=><label key={k}>{l}<input type={t} step="any" disabled={!canEdit} value={teaInputs[k]??''} onChange={e=>setTeaInputs({...teaInputs,[k]:e.target.value===''?'':t==='number'?Number(e.target.value):e.target.value})}/></label>)}<label>核算方法<select value={teaInputs.method} disabled={!canEdit} onChange={e=>setTeaInputs({...teaInputs,method:e.target.value})}><option value="UTILITY_ONLY">部分年度化核算（UTILITY_ONLY）</option></select></label></div><div className="button-row"><button className="primary" disabled={!canEdit||busy} onClick={()=>run(async()=>{await api('/projects/'+p.id+'/tea','POST',teaInputs);await reload()})}>检查输入并计算可支持的指标</button></div></Panel>{p.tea&&<><Notice tone={p.tea.missing_inputs.length?'amber':'cyan'}>{p.tea.status} · {p.tea.missing_inputs.length?'缺少：'+p.tea.missing_inputs.join('、'):'仅计算已具备依据的部分年度化指标，不是完整 TEA。'}</Notice><Panel title="经济与环境指标" kicker="TRACEABLE CALCULATIONS"><table><thead><tr><th>指标</th><th>结果</th><th>状态</th></tr></thead><tbody>{Object.entries(p.tea.metrics).map(([k,v]:any)=><tr key={k}><td>{k}</td><td>{v?<Q q={v} onSource={onSource}/>:'NOT CALCULATED'}</td><td><Badge tone={v?'cyan':'amber'}>{v?'PARTIAL / CALCULATED':'INPUT REQUIRED'}</Badge></td></tr>)}</tbody></table></Panel><Notice>{p.tea.limitations.join(' ')}</Notice></>}</>;
 if(step===9)return <><div className="metrics"><Metric label="工作流进度" value={p.status==='COMPLETE'?'9 / 9 COMPLETE':'8 / 9 · 待最终复核'} tone={p.status==='COMPLETE'?'green':'cyan'}/><Metric label="独立数值验证" value="NOT ASSESSED" tone="amber" sub="需要真实模拟器连接"/><Metric label="模拟后端" value="REFERENCE REPLAY" sub="不是 AI 预测"/></div><Notice>本轮复核的是工作流集成与同源数据映射。不能将回放与标准答案相同解释为 ChemFlow 独立计算准确。</Notice>{p.validation?<Panel title="Golden Evaluator 复核结果" kicker="WORKFLOW VALIDATION"><table><thead><tr><th>检查项</th><th>结果</th><th>依据</th></tr></thead><tbody>{p.validation.checks.map((c:any)=><tr key={c.label}><td>{c.label}</td><td><Badge tone={c.status==='PASS'?'green':'amber'}>{c.status}</Badge></td><td><button className="source-button" onClick={()=>onSource(c.details)}>检查依据 ⓘ</button></td></tr>)}</tbody></table></Panel>:<Panel title="交付前复核清单" kicker="HUMAN REVIEW"><table><tbody>{['设计基准与缺失约束','物性候选和模型人工批准','已选择路线与 SimulationIR','参考回放及原始异常','设备能量与质量衡算','优化问题与参考基线','经济环境输入及未计算项','逐数值来源和审核记录'].map(x=><tr key={x}><td><Check size={14} className="green"/></td><td>{x}</td><td>已记录</td></tr>)}</tbody></table></Panel>}{p.status==='COMPLETE'&&<Panel title="工程成果包" kicker="DELIVERY"><div className="button-row"><a href={'/api/projects/'+p.id+'/report'}><button><Download size={15}/>导出项目报告</button></a><a href={'/api/projects/'+p.id+'/package'}><button className="primary"><Download size={15}/>导出数据成果包</button></a><a href={'/workspace/'+p.id+'/report'}><button><ExternalLink size={15}/>查看复核报告</button></a></div></Panel>}</>;
 return null;
}
''',encoding='utf-8')
print('Nine engineering stage screens implemented.')
